function Dog(name) {
  this.name = name;
}
Dog.prototype.speak = function () {
  return this.name + ' says woof';
};

const a = new Dog('Rex');
const b = new Dog('Fido');
console.log(a.speak()); // Rex says woof
console.log(b.speak()); // Fido says woof
console.log(a.speak === b.speak); // true — same shared function

const base = { kind: 'animal', describe() { return this.kind; } };
const child = Object.create(base);
child.kind = 'dog';

console.log(child.describe()); // dog — method inherited, data own
console.log(child.hasOwnProperty('kind')); // true
console.log(child.hasOwnProperty('describe')); // false — inherited
console.log(Object.getPrototypeOf(child) === base); // true

