solution.code:
function Animal(name) { this.name = name; }
Animal.prototype.getName = function () { return this.name; };

function Cat(name) { Animal.call(this, name); }
Cat.prototype = Object.create(Animal.prototype);
Cat.prototype.constructor = Cat;
Cat.prototype.meow = function () { return 'meow'; };

const c = new Cat('Tom');
console.log(c.getName()); // Tom
console.log(new Animal('x').meow); // undefined — Animals untouched

function myCreate(proto) {
  if (typeof proto !== 'object' && typeof proto !== 'function') {
    throw new TypeError('proto must be an object or null');
  }
  function F() {}
  F.prototype = proto;
  return new F();
}

const base = { hi() { return 'hi'; } };
const obj = myCreate(base);
console.log(obj.hi());                       // hi
console.log(Object.getPrototypeOf(obj) === base); // true
